namespace herc {
namespace {

NSFileManager *fm() { return NSFileManager.defaultManager; }

NSString *ns(const std::string &s) { return [NSString stringWithUTF8String:s.c_str()] ?: @""; }

bool ends_with_ci(const std::string &s, const char *suffix) {
    const size_t n = std::strlen(suffix);
    return s.size() >= n && strcasecmp(s.c_str() + s.size() - n, suffix) == 0;
}

std::string base_name(const std::string &path) {
    const size_t slash = path.find_last_of('/');
    return slash == std::string::npos ? path : path.substr(slash + 1);
}

// The files a .cue names (FILE "x" BINARY), in order: the first is track 1.
std::vector<std::string> cue_files(const std::string &text) {
    std::vector<std::string> out;
    size_t pos = 0;
    while (pos < text.size()) {
        size_t end = text.find('\n', pos);
        if (end == std::string::npos)
            end = text.size();
        std::string line = text.substr(pos, end - pos);
        pos = end + 1;
        const size_t f = line.find("FILE");
        if (f == std::string::npos)
            continue;
        const size_t q1 = line.find('"', f), q2 = q1 == std::string::npos ? q1 : line.find('"', q1 + 1);
        if (q1 != std::string::npos && q2 != std::string::npos)
            out.push_back(base_name(line.substr(q1 + 1, q2 - q1 - 1)));
    }
    return out;
}

std::string read_text(const std::string &path) {
    NSString *s = [NSString stringWithContentsOfFile:ns(path) encoding:NSUTF8StringEncoding error:nil]
                      ?: [NSString stringWithContentsOfFile:ns(path) encoding:NSISOLatin1StringEncoding error:nil];
    return s ? std::string(s.UTF8String) : std::string();
}

// The first .cue in `dir`, or a .cue one folder down (a ZIP unpacked in Files
// usually has the game in a folder of its own).
std::string find_cue(const std::string &dir, int depth = 1) {
    NSArray<NSString *> *names =
        [[fm() contentsOfDirectoryAtPath:ns(dir) error:nil] sortedArrayUsingSelector:@selector(compare:)];
    for (NSString *n in names)
        if ([n.pathExtension caseInsensitiveCompare:@"cue"] == NSOrderedSame && ![n hasPrefix:@"._"])
            return dir + "/" + n.UTF8String;
    if (depth > 0)
        for (NSString *n in names) {
            BOOL is_dir = NO;
            const std::string sub = dir + "/" + n.UTF8String;
            if ([fm() fileExistsAtPath:ns(sub) isDirectory:&is_dir] && is_dir && ![n hasPrefix:@"."]) {
                const std::string c = find_cue(sub, depth - 1);
                if (!c.empty())
                    return c;
            }
        }
    return "";
}

// SHA-1 of a file, reusing the digest cached for the same size and mtime.
std::string sha1_file(const std::string &path, const ProgressFn &progress) {
    struct stat st{};
    if (stat(path.c_str(), &st) != 0)
        return "";
    // Keyed by name, size and time, not the path: the app's own folder moves with every install.
    NSString *key = [NSString stringWithFormat:@"%s|%lld|%ld", base_name(path).c_str(), (long long)st.st_size,
                                               (long)st.st_mtimespec.tv_sec];
    NSDictionary *cache = [NSUserDefaults.standardUserDefaults dictionaryForKey:@"ios.discDigests"];
    if (NSString *hit = cache[key])
        return hit.UTF8String;
    FILE *f = std::fopen(path.c_str(), "rb");
    if (!f)
        return "";
    CC_SHA1_CTX ctx;
    CC_SHA1_Init(&ctx);
    std::vector<unsigned char> buf(4 << 20);
    Progress p;
    p.files_total = 1;
    p.bytes_total = (uint64_t)st.st_size;
    p.current = "Checking " + base_name(path);
    size_t n;
    while ((n = std::fread(buf.data(), 1, buf.size(), f)) > 0) {
        CC_SHA1_Update(&ctx, buf.data(), (CC_LONG)n);
        p.bytes_done += n;
        if (progress)
            progress(p);
    }
    std::fclose(f);
    unsigned char md[CC_SHA1_DIGEST_LENGTH];
    CC_SHA1_Final(md, &ctx);
    char hex[2 * CC_SHA1_DIGEST_LENGTH + 1];
    for (int i = 0; i < CC_SHA1_DIGEST_LENGTH; ++i)
        std::snprintf(hex + 2 * i, 3, "%02x", md[i]);
    NSMutableDictionary *next = [NSMutableDictionary dictionaryWithDictionary:cache ?: @{}];
    if (next.count >= 8)
        [next removeAllObjects];  // a handful of discs at most; older digests are only a cache
    next[key] = @(hex);
    [NSUserDefaults.standardUserDefaults setObject:next forKey:@"ios.discDigests"];
    return hex;
}

bool copy_file(const std::string &from, const std::string &to, const std::atomic<bool> &cancel, Progress &p,
               const ProgressFn &progress, std::string *error) {
    FILE *in = std::fopen(from.c_str(), "rb");
    if (!in) {
        *error = "cannot read " + base_name(from);
        return false;
    }
    FILE *out = std::fopen(to.c_str(), "wb");
    if (!out) {
        std::fclose(in);
        *error = "cannot write " + base_name(to);
        return false;
    }
    std::vector<unsigned char> buf(4 << 20);
    size_t n;
    bool ok = true;
    while ((n = std::fread(buf.data(), 1, buf.size(), in)) > 0) {
        if (cancel || std::fwrite(buf.data(), 1, n, out) != n) {
            ok = false;
            break;
        }
        p.bytes_done += n;
        if (progress)
            progress(p);
    }
    std::fclose(in);
    if (std::fclose(out) != 0)
        ok = false;
    if (!ok && !cancel)
        *error = "could not copy " + base_name(from) + " (is there enough free space?)";
    return ok;
}

uint64_t free_space(const std::string &dir) {
    NSDictionary *a = [fm() attributesOfFileSystemForPath:ns(dir) error:nil];
    return [a[NSFileSystemFreeSize] unsignedLongLongValue];
}

struct ZipWrite {
    FILE *f;
    Progress *p;
    const ProgressFn *progress;
    const std::atomic<bool> *cancel;
};

size_t zip_write(void *opaque, mz_uint64, const void *data, size_t n) {
    ZipWrite *w = (ZipWrite *)opaque;
    if (*w->cancel)
        return 0;
    const size_t wrote = std::fwrite(data, 1, n, w->f);
    w->p->bytes_done += wrote;
    if (*w->progress)
        (*w->progress)(*w->p);
    return wrote;
}

}  // namespace

const char *release_name(const std::string &id) {
    if (id == "SCES-00891") return "English (SCES-00891)";
    if (id == "SCES-00892") return "French (SCES-00892)";
    if (id == "SCES-00893") return "German (SCES-00893)";
    if (id == "SCES-00894") return "Italian (SCES-00894)";
    if (id == "SCES-00895") return "Spanish (SCES-00895)";
    return "an unknown release";
}

std::string human_bytes(uint64_t b) {
    char s[32];
    if (b >= (1ull << 30))
        std::snprintf(s, sizeof s, "%.1f GB", b / 1073741824.0);
    else if (b >= (1ull << 20))
        std::snprintf(s, sizeof s, "%.0f MB", b / 1048576.0);
    else
        std::snprintf(s, sizeof s, "%.0f KB", b / 1024.0);
    return s;
}

DiscStatus check_disc(const std::string &dir, const ProgressFn &progress) {
    DiscStatus st;
    st.root = dir;
    st.cue = find_cue(dir);
    if (st.cue.empty())
        return st;
    const std::string cue_dir = st.cue.substr(0, st.cue.find_last_of('/'));
    const std::vector<std::string> files = cue_files(read_text(st.cue));
    for (const std::string &f : files)
        if (![fm() fileExistsAtPath:ns(cue_dir + "/" + f)])
            st.missing += (st.missing.empty() ? "" : ", ") + f;
    if (files.empty() || !st.missing.empty()) {
        st.state = State::Incomplete;
        if (files.empty())
            st.missing = "the .bin file the .cue names";
        return st;
    }
    const std::string digest = sha1_file(cue_dir + "/" + files[0], progress);
    st.state = State::WrongVersion;
    for (const auto &d : kHercDiscs)
        if (digest == d.sha1) {
            st.found_id = d.id;
            if (st.found_id == HERC_BUILD_DISC_ID)
                st.state = State::Ready;
        }
    return st;
}

ImportResult import_disc(const std::string &source, bool zip, const std::string &dest,
                         const std::atomic<bool> &cancel, const ProgressFn &progress, DiscStatus *status,
                         std::string *error) {
    const std::string staging = dest + ".importing";
    [fm() removeItemAtPath:ns(staging) error:nil];
    [fm() createDirectoryAtPath:ns(staging) withIntermediateDirectories:YES attributes:nil error:nil];
    Progress p;

    if (!zip) {
        const std::string cue = find_cue(source);
        if (cue.empty())
            return ImportResult::NoDisc;
        const std::string dir = cue.substr(0, cue.find_last_of('/'));
        std::vector<std::string> names = cue_files(read_text(cue));
        for (const std::string &n : names) {
            struct stat s{};
            if (stat((dir + "/" + n).c_str(), &s) != 0) {
                *error = n;
                return ImportResult::Incomplete;
            }
            p.bytes_total += (uint64_t)s.st_size;
        }
        if (p.bytes_total + (64ull << 20) > free_space(dest.substr(0, dest.find_last_of('/')))) {
            *error = human_bytes(p.bytes_total);
            return ImportResult::NoSpace;
        }
        names.insert(names.begin(), base_name(cue));
        p.files_total = names.size();
        for (const std::string &n : names) {
            p.current = n;
            if (!copy_file(dir + "/" + n, staging + "/" + n, cancel, p, progress, error))
                return cancel ? ImportResult::Cancelled : ImportResult::Failed;
            p.files_done++;
        }
    } else {
        mz_zip_archive za{};
        if (!mz_zip_reader_init_file(&za, source.c_str(), 0)) {
            *error = "not a ZIP file the app can read";
            return ImportResult::Failed;
        }
        std::unique_ptr<mz_zip_archive, void (*)(mz_zip_archive *)> guard(&za, [](mz_zip_archive *z) {
            mz_zip_reader_end(z);
        });
        // The .cue, then the files it names, wherever they sit in the ZIP.
        int cue_index = -1;
        const mz_uint count = mz_zip_reader_get_num_files(&za);
        auto entry_name = [&](mz_uint i) {
            char name[1024];
            mz_zip_reader_get_filename(&za, i, name, sizeof name);
            return std::string(name);
        };
        for (mz_uint i = 0; i < count && cue_index < 0; ++i) {
            const std::string n = entry_name(i);
            if (ends_with_ci(n, ".cue") && base_name(n).rfind("._", 0) != 0)
                cue_index = (int)i;
        }
        if (cue_index < 0)
            return ImportResult::NoDisc;
        size_t cue_size = 0;
        char *cue_text = (char *)mz_zip_reader_extract_to_heap(&za, cue_index, &cue_size, 0);
        const std::string cue(cue_text ? cue_text : "", cue_size);
        mz_free(cue_text);
        std::vector<std::pair<std::string, int>> wanted{{base_name(entry_name(cue_index)), cue_index}};
        for (const std::string &n : cue_files(cue)) {
            int found = -1;
            for (mz_uint i = 0; i < count && found < 0; ++i)
                if (base_name(entry_name(i)) == n)
                    found = (int)i;
            if (found < 0) {
                *error = n;
                return ImportResult::Incomplete;
            }
            wanted.push_back({n, found});
        }
        for (const auto &w : wanted) {
            mz_zip_archive_file_stat s;
            mz_zip_reader_file_stat(&za, w.second, &s);
            p.bytes_total += s.m_uncomp_size;
        }
        if (p.bytes_total + (64ull << 20) > free_space(dest.substr(0, dest.find_last_of('/')))) {
            *error = human_bytes(p.bytes_total);
            return ImportResult::NoSpace;
        }
        p.files_total = wanted.size();
        for (const auto &w : wanted) {
            p.current = w.first;
            FILE *f = std::fopen((staging + "/" + w.first).c_str(), "wb");
            if (!f) {
                *error = "cannot write " + w.first;
                return ImportResult::Failed;
            }
            ZipWrite zw{f, &p, &progress, &cancel};
            const bool ok = mz_zip_reader_extract_to_callback(&za, w.second, zip_write, &zw, 0);
            const bool closed = std::fclose(f) == 0;
            if (cancel)
                return ImportResult::Cancelled;
            if (!ok || !closed) {
                *error = "could not unpack " + w.first + " (is there enough free space?)";
                return ImportResult::Failed;
            }
            p.files_done++;
        }
    }

    DiscStatus st = check_disc(staging, progress);
    if (status)
        *status = st;
    if (st.state == State::WrongVersion) {
        [fm() removeItemAtPath:ns(staging) error:nil];
        return ImportResult::WrongVersion;
    }
    if (st.state != State::Ready) {
        *error = st.missing;
        return ImportResult::Incomplete;
    }
    [fm() removeItemAtPath:ns(dest) error:nil];
    NSError *err = nil;
    if (![fm() moveItemAtPath:ns(staging) toPath:ns(dest) error:&err]) {
        *error = err.localizedDescription.UTF8String;
        return ImportResult::Failed;
    }
    // A disc is the player's to back up, not iCloud's.
    NSURL *url = [NSURL fileURLWithPath:ns(dest)];
    [url setResourceValue:@YES forKey:NSURLIsExcludedFromBackupKey error:nil];
    if (status)
        *status = check_disc(dest);
    return ImportResult::Ok;
}

bool export_saves(const std::string &saves_dir, const std::string &zip_path, std::string *error) {
    mz_zip_archive za{};
    if (!mz_zip_writer_init_file(&za, zip_path.c_str(), 0)) {
        *error = "cannot write " + base_name(zip_path);
        return false;
    }
    bool ok = true;
    NSDirectoryEnumerator *e = [fm() enumeratorAtPath:ns(saves_dir)];
    for (NSString *rel in e) {
        BOOL is_dir = NO;
        const std::string full = saves_dir + "/" + rel.UTF8String;
        if ([fm() fileExistsAtPath:ns(full) isDirectory:&is_dir] && !is_dir)
            ok = ok && mz_zip_writer_add_file(&za, rel.UTF8String, full.c_str(), nullptr, 0, MZ_DEFAULT_COMPRESSION);
    }
    ok = mz_zip_writer_finalize_archive(&za) && ok;
    mz_zip_writer_end(&za);
    if (!ok)
        *error = "the ZIP could not be written";
    return ok;
}

bool import_saves(const std::string &zip_path, const std::string &saves_dir, std::string *error) {
    mz_zip_archive za{};
    if (!mz_zip_reader_init_file(&za, zip_path.c_str(), 0)) {
        *error = "not a ZIP file the app can read";
        return false;
    }
    bool ok = true;
    const mz_uint count = mz_zip_reader_get_num_files(&za);
    for (mz_uint i = 0; i < count && ok; ++i) {
        if (mz_zip_reader_is_file_a_directory(&za, i))
            continue;
        char name[1024];
        mz_zip_reader_get_filename(&za, i, name, sizeof name);
        const std::string n = name;
        if (n.empty() || n[0] == '/' || n.find("..") != std::string::npos || n.rfind("__MACOSX", 0) == 0)
            continue;  // never outside the saves folder
        const std::string out = saves_dir + "/" + n;
        [fm() createDirectoryAtPath:[ns(out) stringByDeletingLastPathComponent]
            withIntermediateDirectories:YES
                             attributes:nil
                                  error:nil];
        ok = mz_zip_reader_extract_to_file(&za, i, out.c_str(), 0);
    }
    mz_zip_reader_end(&za);
    if (!ok)
        *error = "the ZIP could not be read completely";
    return ok;
}

}  // namespace herc
